pub fn break_sentence (s : & str) -> Vec < usize > { use icu_segmenter :: SentenceBreakSegmenter ; let provider = icu_testdata :: get_provider () ; let segmenter = SentenceBreakSegmenter :: try_new (& provider) . expect ("Data exists") ; let breakpoints : Vec < usize > = segmenter . segment_str (s) . collect () ; breakpoints } # [cfg (test)] mod tests { use super :: * ; # [test] fn test_break_sentence () { println ! ("{:?}" , break_sentence ("Hello World. Hello world.")) ; } }